<script setup lang="ts">import {ref,computed} from 'vue';import PageHeading from '../components/common/PageHeading.vue';import Table from '../components/common/Table.vue';import Notice from '../components/common/Notice.vue';import Status from '../components/common/Status.vue';import {sourceApi} from '../api/source';import {useTask} from '../hooks/useTask';const p=defineProps<{studies:any[];specimens:any[];votes:any[];concepts:any[];quarantine:any[];locales:Record<string,string>;user:any;reloadSource:()=>Promise<void>;reloadTaxonomy:()=>Promise<void>}>();const id=ref(0),study=computed(()=>p.studies.find(s=>s.id===(id.value||p.studies[0]?.id))),items=computed(()=>p.specimens.filter(s=>s.study_id===study.value?.id)),task=useTask(),aliasName=ref(''),aliasCode=ref(''),aliasLocale=ref('zh-CN'),importLocale=ref('zh-CN'),verify=ref<any>(null),renameCode=ref(''),renameName=ref(''),renameLocale=ref('zh-CN'),resolving=ref<Record<number,string>>({});const scheme=computed<any[]>(()=>study.value?.category_scheme||[]);const names=(entry:any)=>entry.name;const vote=(item:any,r:string)=>p.votes.find(v=>v.specimen_id===item.id&&v.rater===r);const display=(v:any)=>v?v.category+(v.category_code?' · '+v.category_code:''):'缺票';async function saveVote(v:any,e:Event){await task.act(async()=>{await sourceApi.editVote(v.id,(e.target as HTMLSelectElement).value);await p.reloadSource()},'逐票修订已保存，既有运行保留冻结结果')}async function create(){await task.act(async()=>{const s=await sourceApi.create(JSON.parse(raw.value),importLocale.value);await p.reloadSource();await p.reloadTaxonomy();id.value=s.id},'完整面板研究已保存，类别已分配稳定编码')}function annotate(s:any){const d=prompt('试样说明',s.description);if(d!==null)task.act(async()=>{await sourceApi.editSpecimen(s.id,d);await p.reloadSource()},'试样说明已保存')}async function addAlias(){await task.act(async()=>{await sourceApi.addAlias(study.value.id,{code:aliasCode.value||scheme.value[0]?.code,name:aliasName.value,locale:aliasLocale.value});await p.reloadSource();await p.reloadTaxonomy()},'同义名已登记')}async function rename(){await task.act(async()=>{await sourceApi.renameCategory(renameCode.value,{name:renameName.value,locale:renameLocale.value});await p.reloadTaxonomy();await p.reloadSource()},'已生成新版本；历史运行与已批准说明保留原显示名')}async function migrate(){await task.act(async()=>{const r=await sourceApi.migrate();verify.value=r;await p.reloadTaxonomy();await p.reloadSource()},'迁移完成；重复执行不会新增或改写记录')}async function check(){await task.act(async()=>{verify.value=await sourceApi.verify()},'已核对编码覆盖情况')}async function resolveQ(q:any){if(!resolving.value[q.id])return;await task.act(async()=>{await sourceApi.resolveQuarantine(q.id,resolving.value[q.id]);await p.reloadTaxonomy()},'隔离记录已解决')}const example={name:'四试样完整面板手算输入',filename:'sx-four-items-three-raters.json',description:'完整面板；类别顺序预先固定',categories:['砂岩','泥岩'],raters:['A','B','C'],specimens:[['砂岩','砂岩','砂岩'],['砂岩','砂岩','泥岩'],['砂岩','泥岩','泥岩'],['泥岩','泥岩','泥岩']].map((labels,i)=>({reference:'HAND-'+(i+1),description:'独立试样图像',votes:labels.map((category,j)=>({rater:['A','B','C'][j],category}))}))};const raw=ref(JSON.stringify(example,null,2));</script><template><PageHeading index="02" title="逐票核对，面板不能少一人。" description="每试样相同三人各一票；类别保存稳定编码，显示名可多语言、同义名与版本化。"/><label>来源研究<select :value="study?.id||0" @change="id=Number(($event.target as HTMLSelectElement).value)"><option v-for="s in studies" :key="s.id" :value="s.id">{{s.name}}</option></select></label><p v-if="study">{{study.filename}} / {{study.description}}<br/>面板 {{study.raters.join(' / ')}} · 类别 {{study.categories.join(' / ')}}</p><div v-if="scheme.length" class="taxonomy-strip"><div class="section-head"><h2>类别编码与显示名</h2><span>顺序即计数顺序；编码不随改名变化</span></div><Table :headers="['序','稳定编码','研究声明名','当前中文','English','版本']"><tr v-for="(entry,i) in scheme" :key="entry.code||i"><td>{{i+1}}</td><td><code>{{entry.code||'未迁移·仅名称'}}</code></td><td>{{entry.declared_name||entry.name}}</td><td>{{entry.name}}</td><td>{{p.concepts.find(c=>c.code===entry.code)?.names?.['en']?.name||'—'}}</td><td>{{entry.term_version??'—'}}</td></tr></Table></div><div class="source-layout"><section><h2>完整面板 / 前16试样</h2><Table :headers="['试样',...(study?.raters||[]),'说明']"><tr v-for="item in items.slice(0,16)" :key="item.id"><td>{{item.reference}}</td><td v-for="r in study?.raters" :key="r"><select v-if="user.role!=='viewer'&&vote(item,r)" :aria-label="'类别-'+vote(item,r).id" :value="vote(item,r).category" @change="saveVote(vote(item,r),$event)"><option v-for="entry in (scheme.length?scheme:study.categories.map((c:string)=>({code:c,name:c})))" :key="entry.code||entry.name" :value="entry.code||entry.name">{{entry.name}} · {{entry.code||'未编码'}}</option></select><span v-else>{{display(vote(item,r))}}</span></td><td><button v-if="user.role!=='viewer'" @click="annotate(item)">补注</button></td></tr></Table></section><section class="input-sheet"><small>NEW FIXED-PANEL STUDY</small><h2>导入独立试样逐票</h2><p>2–240个试样、声明2–6类和固定3人；缺票、重复人、未知类、重复试样编号均拒绝。新名称在同一语言下重复映射会被拒绝。</p><form v-if="user.role!=='viewer'" @submit.prevent="create"><label>导入语言<select v-model="importLocale"><option v-for="(label,key) in p.locales" :key="key" :value="key">{{label}}</option></select></label><label>研究 JSON<textarea v-model="raw" rows="20"/></label><button class="primary" :disabled="task.state.busy">保存完整面板研究 →</button></form><p v-else>观察员可读底稿；导入和改票由分析员处理。</p><Notice v-bind="task.state"/></section></div><section v-if="user.role!=='viewer'&&scheme.length" class="input-sheet"><h2>同义名登记</h2><p>同义名解析到同一稳定编码；已属于其他类别的名称会被拒绝。</p><div class="field-pair"><label>目标编码<select v-model="aliasCode"><option v-for="entry in scheme" :key="entry.code" :value="entry.code">{{entry.code}} · {{entry.name}}</option></select></label><label>同义名<input v-model="aliasName" required/></label></div><label>语言<select v-model="aliasLocale"><option v-for="(label,key) in p.locales" :key="key" :value="key">{{label}}</option></select></label><button :disabled="task.state.busy||!aliasName" @click.prevent="addAlias">登记同义名</button><Notice v-bind="task.state"/></section><section class="section"><div class="section-head"><h2>类别版本与隔离</h2><span>改名只影响新运行</span></div><div class="field-pair"><label>类别编码<input v-model="renameCode" placeholder="CAT-…"/></label><label>新显示名<input v-model="renameName"/></label></div><label>语言<select v-model="renameLocale"><option v-for="(label,key) in p.locales" :key="key" :value="key">{{label}}</option></select></label><button v-if="user.role==='admin'" :disabled="task.state.busy||!renameCode||!renameName" @click.prevent="rename">追加新版本名称</button><p v-else>仅负责人可追加新版本名称；分析员可登记同义名与导入。</p><div class="memo-actions"><button :disabled="task.state.busy" @click.prevent="migrate">运行旧数据迁移（可重复执行）</button><button :disabled="task.state.busy" @click.prevent="check">核对编码覆盖</button></div><Notice v-bind="task.state"/><div v-if="verify" class="snapshot-line">迁移：研究{{verify.studies?.length??verify.studies??0}} / 隔离{{verify.open_quarantine??0}}<span v-for="s in verify.studies||[]" :key="s.study_id">　#{{s.study_id}} {{s.name}}：{{s.coded_votes}}/{{s.total_votes}}票有编码<span v-if="s.duplicate_codes">，重复编码{{s.duplicate_codes}}</span><span v-if="s.legacy">，尚未迁移</span></span></div><h2>隔离队列</h2><p>未知或重复映射的名称不静默丢弃，保留原名称并说明原因；处置后仍保留记录。</p><Table :headers="['来源','研究','原名称','原因','状态','处置']"><tr v-for="q in p.quarantine" :key="q.id"><td>{{q.source}}</td><td>{{q.study_id??'—'}}</td><td>{{q.raw_name}}</td><td><code>{{q.reason_code}}</code><br/>{{q.reason}}</td><td>{{q.status==='open'?'待处理':'已解决'}}</td><td><template v-if="q.status==='open'"><input v-model="resolving[q.id]" placeholder="目标编码"/><button v-if="user.role==='admin'" @click="resolveQ(q)">标记解决</button></template><span v-else>{{q.resolved_code}}</span></td></tr></Table></section></template>
